/**
 * @summary Add a review to a profile
 */
export const getAddProfileReviewUrl = (slug: string) => {
  return `/api/profiles/${slug}/reviews`;
};

export const addProfileReview = async (
  slug: string,
  addProfileReviewBody: AddProfileReviewBody,
  options?: RequestInit,
): Promise<ProfileReview> => {
  return customFetch<ProfileReview>(getAddProfileReviewUrl(slug), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(addProfileReviewBody),
  });
};

export const getAddProfileReviewMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof addProfileReview>>,
    TError,
    { slug: string; data: BodyType<AddProfileReviewBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof addProfileReview>>,
  TError,
  { slug: string; data: BodyType<AddProfileReviewBody> },
  TContext
> => {
  const mutationKey = ["addProfileReview"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof addProfileReview>>,
    { slug: string; data: BodyType<AddProfileReviewBody> }
  > = (props) => {
    const { slug, data } = props ?? {};

    return addProfileReview(slug, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

